<?php require_once __DIR__.'/../config/bootstrap.php'; require_client();$pdo=db();$pageTitle='Nova Encomenda';$cid=current_user()['id'];$products=$pdo->query('SELECT id,nome,preco,codigo FROM produtos WHERE ativo=1 ORDER BY nome')->fetchAll();$cart=$_SESSION['client_order']??[];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';if($action==='add'){ $pid=(int)$_POST['produto_id'];$q=max(.01,number_value($_POST['quantidade']??1));if(isset($cart[$pid]))$cart[$pid]['qty']+=$q;else{$st=$pdo->prepare('SELECT id,nome,preco FROM produtos WHERE id=? AND ativo=1');$st->execute([$pid]);$p=$st->fetch();if($p)$cart[$pid]=['id'=>(int)$p['id'],'nome'=>$p['nome'],'preco'=>(float)$p['preco'],'qty'=>$q];}$_SESSION['client_order']=$cart;redirect('nova-encomenda.php');}if($action==='remove'){$pid=(int)$_POST['produto_id'];unset($cart[$pid]);$_SESSION['client_order']=$cart;redirect('nova-encomenda.php');}if($action==='send'){$obs=trim($_POST['observacoes']??'');$sub=0;foreach($cart as $i)$sub+=$i['qty']*$i['preco'];if(!$cart){$error='Adicione pelo menos um produto.';}else{$pdo->beginTransaction();try{$num=next_number('ENC','encomendas');$pdo->prepare("INSERT INTO encomendas(numero,cliente_id,usuario_id,origem,data_hora,subtotal,desconto,total,status,observacoes) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$num,$cid,null,'portal',now(),$sub,0,$sub,'Aberta',$obs]);$eid=(int)$pdo->lastInsertId();$is=$pdo->prepare('INSERT INTO encomenda_itens(encomenda_id,produto_id,quantidade,preco_unitario,subtotal) VALUES(?,?,?,?,?)');foreach($cart as $i)$is->execute([$eid,$i['id'],$i['qty'],$i['preco'],$i['qty']*$i['preco']]);$pdo->prepare('INSERT INTO encomenda_status_historico(encomenda_id,status_anterior,status_novo,usuario_id,data_hora) VALUES(?,?,?,?,?)')->execute([$eid,null,'Aberta',null,now()]);$pdo->commit();log_action('encomenda de cliente','encomendas',$eid);unset($_SESSION['client_order']);flash('success','Encomenda criada com sucesso.');redirect('encomenda.php?id='.$eid);}catch(Throwable $e){$pdo->rollBack();$error='Não foi possível enviar a encomenda.';}}}}
$total=0;foreach($cart as $i)$total+=$i['qty']*$i['preco'];include __DIR__.'/../includes/header.php'; ?><div class="page-head"><div><h1>Nova Encomenda</h1><div class="muted">Seu cadastro já está associado à encomenda.</div></div></div><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><div class="grid grid-2"><div class="card"><h3>Produtos</h3><form class="search-row" onsubmit="return false"><input id="filter" placeholder="Pesquisar produto"><span></span></form><div id="product-list" style="display:grid;gap:8px;margin-top:12px"></div></div><div class="card"><h3>Minha encomenda</h3><?php foreach($cart as $i): ?><div class="cart-item"><div><strong><?=e($i['nome'])?></strong><div><?=$i['qty']?> × <?=money($i['preco'])?></div></div><div><strong><?=money($i['qty']*$i['preco'])?></strong><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="produto_id" value="<?=$i['id']?>"><button class="btn small secondary">Remover</button></form></div></div><?php endforeach;if(!$cart): ?><div class="empty">Nenhum item ainda.</div><?php endif; ?><div class="total-line total"><span>Total</span><strong><?=money($total)?></strong></div><form method="post" style="margin-top:13px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="send"><div class="field"><label>Observações</label><textarea name="observacoes"></textarea></div><button class="btn primary w100" <?=$cart?'':'disabled'?>>Enviar encomenda</button></form></div></div><script>const CLIENT_PRODUCTS=<?=json_encode($products,JSON_UNESCAPED_UNICODE)?>;function renderProducts(){const q=document.getElementById('filter').value.toLowerCase();const box=document.getElementById('product-list');box.innerHTML='';CLIENT_PRODUCTS.filter(p=>(p.nome+' '+p.codigo).toLowerCase().includes(q)).slice(0,80).forEach(p=>{const f=document.createElement('form');f.method='post';f.className='product-card';f.innerHTML='<input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="produto_id" value="'+p.id+'"><div class="pname">'+p.nome+'</div><div class="muted">'+p.codigo+'</div><div class="price">R$ '+Number(p.preco).toFixed(2).replace('.',',')+'</div><div class="inline"><input class="input" style="width:90px" type="number" step="0.01" min="0.01" name="quantidade" value="1"><button class="btn small primary">Adicionar</button></div>';box.appendChild(f)})}document.getElementById('filter').addEventListener('input',renderProducts);renderProducts();</script><?php include __DIR__.'/../includes/footer.php'; ?>
